import{_ as a,a as t,c as o,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 1 A private conversation","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 1 A private conversation","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第二册：实践与进步 · Lesson 2 Breakfast or lunch?","link":"/life/english/new-concept/book-2/unit-01/lesson-002"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第二册：实践与进步 · Lesson 2 Breakfast or lunch?","link":"/life/english/new-concept/book-2/unit-01/lesson-002"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-001.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-001.md"}'),n={name:"life/english/new-concept/book-2/unit-01/lesson-001.md"};function l(r,e,s,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-1-a-private-conversation" tabindex="-1">第二册：实践与进步 · Lesson 1 A private conversation <a class="header-anchor" href="#第二册-实践与进步-·-lesson-1-a-private-conversation" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 1 A private conversation&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>在图书馆里，一次低声交谈仍然打断了旁人的阅读；练习交代动作发生的地点与方式。本课的语言观察是：讲述已经结束的小冲突时，用过去式推进“听见、转身、离开”的动作，副词 quietly 修饰说话方式，而不是修饰说话者的身份。完成学习后，请用三句描述一次公共场所的小打扰，包括地点、反应和解决办法。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>seat</td><td>/siːt/</td><td>n.</td><td>座位</td><td>an empty seat</td></tr><tr><td>quiet</td><td>/ˈkwaɪət/</td><td>adj.</td><td>安静的</td><td>a quiet room</td></tr><tr><td>voice</td><td>/vɔɪs/</td><td>n.</td><td>嗓音</td><td>a low voice</td></tr><tr><td>notice</td><td>/ˈnəʊtɪs/</td><td>v.</td><td>注意到</td><td>notice a change</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>lower your voice — 压低声音；voice 前用物主代词</li><li>pay attention to — 注意；to 后接名词或动名词</li></ul><h2 id="语法讲解-一般过去时与事件顺序" tabindex="-1">语法讲解：一般过去时与事件顺序 <a class="header-anchor" href="#语法讲解-一般过去时与事件顺序" aria-label="Permalink to &quot;语法讲解：一般过去时与事件顺序&quot;">​</a></h2><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：讲述已经结束的小冲突时，用过去式推进“听见、转身、离开”的动作，副词 quietly 修饰说话方式，而不是修饰说话者的身份。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Maya closed her book quietly after the discussion.</p></blockquote><p>讨论结束后，玛雅轻轻合上了书。</p><p>Maya 是主语，closed 是过去式谓语，her book 是宾语，quietly 是方式状语，after 短语标记时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>录下示范，重读 closed、book、quietly；比较 quiet 与 quietly 的音节数量。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Maya closed her book quietly after the discussion. A student nearby asked for silence. Maya moved to the entrance to finish her conversation.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描述一次公共场所的小打扰，包括地点、反应和解决办法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Maya 是主语，closed 是过去式谓语，her book 是宾语，quietly 是方式状语，after 短语标记时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填入 close 的一般过去式：Maya ___ her book quietly.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> closed</p><p><strong>解析：</strong> close 规则变化加 -d，句中讲述已经发生的动作。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>玛雅后来到哪里继续交谈？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She moved to the entrance.</p><p><strong>解析：</strong> 示范最后一句明确给出 entrance，不是 seat。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 Maya closed her book 改为否定句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Maya did not close her book.</p><p><strong>解析：</strong> did not 已标记过去，close 必须用原形。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时与事件顺序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-002">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",l]]);export{p as __pageData,b as default};
